const fs = require('fs');
const path = require('path');

/**
 * Writes testing/corpus/schemas.generated.ts, an explicit import of every
 * example schema that is valid JSON.
 *
 * This replaces require.context, which Angular 15 stopped providing: its
 * builder no longer defines it, so the call fails at run time with
 * "__webpack_require__(...).context is not a function". Explicit imports work
 * on every Angular version and will survive the move to Vitest.
 *
 * Four example schemas embed JavaScript event handlers and are not valid JSON.
 * The demo evals those; a bundler parses JSON at build time, so importing them
 * breaks the build. They are skipped here and the count is asserted in the
 * spec so a fifth cannot appear unnoticed.
 */
const SCHEMA_DIR = path.join(__dirname, '..', 'demo', 'assets', 'example-schemas');
const OUTPUT = path.join(__dirname, '..', 'testing', 'corpus', 'schemas.generated.ts');

function generate() {
  const loadable = [];
  const skipped = [];

  for (const file of fs.readdirSync(SCHEMA_DIR).filter((f) => f.endsWith('.json')).sort()) {
    const name = file.replace(/\.json$/, '');
    try {
      JSON.parse(fs.readFileSync(path.join(SCHEMA_DIR, file), 'utf8'));
      loadable.push(name);
    } catch (error) {
      skipped.push(name);
    }
  }

  const ident = (name) => 's_' + name.replace(/[^a-zA-Z0-9]/g, '_');
  const lines = [
    '// Generated by scripts/generate-corpus-index.js. Do not edit.',
    '// Run `npm run corpus:index` after adding or removing an example schema.',
    '',
    ...loadable.map((n) => `import ${ident(n)} from '../../demo/assets/example-schemas/${n}.json';`),
    '',
    '/** Example schemas that are not valid JSON, so a bundler cannot import them. */',
    `export const SKIPPED_NOT_JSON: string[] = ${JSON.stringify(skipped, null, 2)};`,
    '',
    'export const CORPUS: { name: string; form: any }[] = [',
    ...loadable.map((n) => `  { name: '${n}', form: ${ident(n)} },`),
    '];',
    '',
  ];

  fs.writeFileSync(OUTPUT, lines.join('\n'));
  return { loadable: loadable.length, skipped };
}

if (require.main === module) {
  const result = generate();
  console.log(
    `[corpus-index] ${result.loadable} schemas, ${result.skipped.length} skipped: ${result.skipped.join(', ')}`
  );
}

module.exports = { generate };
